  "history": `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200" role="img" aria-labelledby="il-history-t" font-family="system-ui,-apple-system,'Segoe UI','Microsoft JhengHei','PingFang TC','Noto Sans TC',sans-serif" fill="#1e293b"><title id="il-history-t">物理學史</title><rect x="8" y="90" width="254" height="20" fill="#fde68a" rx="3" stroke="#334155" stroke-width="1"/><rect x="262" y="90" width="52" height="20" fill="#c7d2fe" rx="3" stroke="#334155" stroke-width="1"/><text x="136" y="106" font-size="10" text-anchor="middle" fill="#78350f" font-weight="bold">古典物理 classical physics</text><text x="288" y="106" font-size="10" text-anchor="middle" fill="#312e81" font-weight="bold">近代</text><circle cx="30" cy="90" r="4" fill="#b45309" stroke="#fff" stroke-width="1.2"/><line x1="30" y1="86" x2="30" y2="38" stroke="#b45309" stroke-width="1"/><rect x="6" y="8" width="112" height="30" fill="#fff" rx="5" stroke="#b45309" stroke-width="1.2"/><text x="62" y="21" font-size="10" text-anchor="middle" fill="#b45309" font-weight="bold">1687 牛頓力學</text><text x="62" y="34" font-size="10" text-anchor="middle" fill="#334155">Newton 萬有引力</text><circle cx="82" cy="90" r="4" fill="#0369a1" stroke="#fff" stroke-width="1.2"/><line x1="82" y1="110" x2="82" y2="114" stroke="#0369a1" stroke-width="1"/><rect x="26" y="114" width="112" height="30" fill="#fff" rx="5" stroke="#0369a1" stroke-width="1.2"/><text x="82" y="127" font-size="10" text-anchor="middle" fill="#0369a1" font-weight="bold">1690 惠更斯</text><text x="82" y="140" font-size="10" text-anchor="middle" fill="#334155">光的波動說 wave</text><circle cx="136" cy="90" r="4" fill="#b91c1c" stroke="#fff" stroke-width="1.2"/><line x1="136" y1="86" x2="136" y2="80" stroke="#b91c1c" stroke-width="1"/><rect x="80" y="50" width="112" height="30" fill="#fff" rx="5" stroke="#b91c1c" stroke-width="1.2"/><text x="136" y="63" font-size="10" text-anchor="middle" fill="#b91c1c" font-weight="bold">1704 牛頓光學</text><text x="136" y="76" font-size="10" text-anchor="middle" fill="#334155">光的微粒說 corpuscle</text><circle cx="186" cy="90" r="4" fill="#0369a1" stroke="#fff" stroke-width="1.2"/><line x1="186" y1="110" x2="186" y2="152" stroke="#0369a1" stroke-width="1"/><rect x="130" y="152" width="112" height="30" fill="#fff" rx="5" stroke="#0369a1" stroke-width="1.2"/><text x="186" y="165" font-size="10" text-anchor="middle" fill="#0369a1" font-weight="bold">1801 楊氏雙狹縫</text><text x="186" y="178" font-size="10" text-anchor="middle" fill="#334155">干涉 → 支持波動說</text><circle cx="240" cy="90" r="4" fill="#6d28d9" stroke="#fff" stroke-width="1.2"/><line x1="240" y1="86" x2="240" y2="38" stroke="#6d28d9" stroke-width="1"/><rect x="184" y="8" width="112" height="30" fill="#fff" rx="5" stroke="#6d28d9" stroke-width="1.2"/><text x="240" y="21" font-size="10" text-anchor="middle" fill="#6d28d9" font-weight="bold">1887 邁克生-莫雷</text><text x="240" y="34" font-size="10" text-anchor="middle" fill="#334155">否定以太說 aether</text><text x="312" y="82" font-size="10" text-anchor="end" fill="#312e81">1905 相對論</text><text x="270" y="132" font-size="10" text-anchor="middle" fill="#6d28d9">以太：假想</text><text x="270" y="145" font-size="10" text-anchor="middle" fill="#6d28d9">傳光介質</text></svg>`,
